import json

def exists(path):
    return execute_tool('editor_toolset.toolsets.asset.AssetTools.exists', json.dumps({'path': path}))['returnValue']

def duplicate(source, destination):
    if exists(destination):
        return 'existing'
    ok = execute_tool('editor_toolset.toolsets.asset.AssetTools.duplicate', json.dumps({'path': source, 'new_path': destination}))['returnValue']
    if not ok:
        raise RuntimeError('Failed to duplicate ' + source + ' to ' + destination)
    return 'created'

def save(paths):
    return execute_tool('editor_toolset.toolsets.asset.AssetTools.save_assets', json.dumps({'asset_paths': paths}))['returnValue']

def run():
    copies = {
        '/ExtractionOps/Experiences/B_ExtractionExperience': '/ShooterCore/Experiences/B_ShooterGame_Elimination',
        '/ExtractionOps/Experiences/DA_ExtractionActionSet': '/ShooterCore/Experiences/LAS_ShooterGame_StandardHUD',
        '/ExtractionOps/Pawns/DA_ExtractionPawnData': '/ShooterCore/Game/HeroData_ShooterGame',
        '/ExtractionOps/UI/W_ExtractionHUDLayout': '/ShooterCore/UserInterface/W_ShooterHUDLayout',
        '/ExtractionOps/Pawns/DA_ExtractionInputConfig': '/Game/Input/InputData_Hero'
    }
    results = {}
    for destination, source in copies.items():
        results[destination] = duplicate(source, destination)
    if not save(list(copies.keys())):
        raise RuntimeError('Failed to save Week 2 core assets')
    return {'assets': results, 'saved': True}
